import type { ClientRunView } from "@/backend/client";

export function makeClientRun(
  overrides: Partial<ClientRunView> = {},
): ClientRunView {
  const rules = overrides.rules ?? {
    pointsRequired: 0,
    maxMoves: 100,
    difficulty: 7,
    primary: { kind: 0, value: 0, requiredCount: 0 },
    secondary: { kind: 0, value: 0, requiredCount: 0 },
    activeMutatorId: 8,
    bossId: 0,
    guardian: { bonus: 1, trigger: 2, threshold: 4 },
    startingRows: 4,
  };
  return {
    runId: 7n,
    mode: "daily",
    mapId: 8,
    level: 1,
    lifecycle: "playing",
    score: 18_450,
    dailyScore: 24_180,
    pressureScore: 80,
    objectiveTotal: 480n,
    actionCounter: 27,
    moves: 26,
    comboCounter: 2,
    maxCombo: 5,
    primaryProgress: 0,
    secondaryProgress: 0,
    latchedStarSources: 0,
    streak: 0,
    chargesEarned: 0,
    levelLinesCleared: 11,
    totalLinesCleared: 11,
    currentTier: 5,
    currentDifficulty: 5,
    bonusType: 1,
    bonusCharges: 2,
    rerollCharges: 1,
    grid: Array<number>(80).fill(0),
    nextRow: [3, 3, 3, 0, 2, 2, 1, 0],
    pendingVrfCounter: 0,
    vrfRequestCounter: 12,
    rulesHash: Array<number>(32).fill(0x33),
    replayHash: Array<number>(32).fill(0x42),
    dailyTheme: { kind: 4, value: 2 },
    dailyPressure: { maxMoves: 100 },
    ...overrides,
    rules,
  };
}
